import * as T from '../vendor/three.module.min.js';
export function treasurePortal(v,t){const g=new T.Group(),orbit=new T.Group();g.add(orbit);for(const [scale,color]of [[1.1,t.crystal],[1.3,0xffdc8c]]){const ring=v.mesh(v.ring,color,.8);ring.position.y=1.75;ring.scale.set(scale,scale*1.35,1);g.add(ring);}const floor=v.mesh(v.ring,0xffde9a,.6);floor.rotation.x=-Math.PI/2;floor.scale.setScalar(1.45);floor.position.y=.05;g.add(floor);v.block(g,0xb77b66,0,.38,0,1,.65,.65);v.block(g,0xffd891,0,.72,0,1.08,.22,.7,.3);v.block(g,0xffeabb,0,.42,.36,.18,.32,.06,.6);for(let i=0;i<8;i++){const m=v.mesh(v.gem,i%2?0xffe6a6:t.crystal,.8);m.scale.setScalar(i%2?.13:.2);orbit.add(m);}g.userData.magicOrbit=orbit;const tag=v.label('SECRET QUEST • 2 QUESTIONS','#fff0bc');tag.scale.set(4,.6,1);tag.position.y=4;g.add(tag);return g;}
export function animatePortal(g,time){g.userData.magicOrbit.children.forEach((m,i)=>{const angle=time*1.4+i*Math.PI/4;m.position.set(Math.cos(angle)*1.25,1.75+Math.sin(angle)*1.65,.12+Math.sin(time+i)*.2);m.rotation.y=time*2;});}
export function energyBlast(v){const g=new T.Group(),core=v.mesh(v.gem,0xb8ffff,1);core.scale.set(.4,.4,1);g.add(core);for(const z of [-.4,.3,.8]){const ring=v.mesh(v.ring,0x9deef5,.8);ring.scale.setScalar(.35+z*.12);ring.position.z=z;g.add(ring);}return g;}
export function updateMagicHud(r){const b=document.querySelector('[data-action="power"]');if(!b)return;const ready=r.stock[r.selectedPower]>0,active=r.active?.kind===r.selectedPower,label=r.selectedPower==='dash'?'SMASH':r.selectedPower.toUpperCase(),caption=active?`${label} ${Math.ceil(r.active.left)}s`:ready?label:'CHARGING';b.classList.toggle('charged',ready);b.classList.toggle('magic-active',active);b.dataset.magic=r.selectedPower;b.setAttribute('aria-label',`${label} power, ${active?'active for '+Math.ceil(r.active.left)+' seconds':r.stock[r.selectedPower]+' charges'}`);const text=b.querySelector('small');if(text&&text.textContent!==caption)text.textContent=caption;}
